# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def _student(last, email="a@x.org"):
    return Student("1", last, "Pat", "A", email)


class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows(
            [_student("Zed"), _student("Abe", "b@x.org")]
        )
        self.assertEqual(
            rows,
            [
                "Abe, Pat             A        b@x.org",
                "Zed, Pat             A        a@x.org"
            ]
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([_student("Zed", None)])
        self.assertIn("Zed, Pat", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
